/* ------------------------------ helpers --------------------------- */

function int(v, d) {
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : d;
}
function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}
const tty = process.stdout.isTTY;
const paint = (c, s) => (tty ? "\x1b[" + c + "m" + s + "\x1b[0m" : s);
const log = (...a) => console.log("[marzneshin]", ...a);
const ok = (...a) => console.log(paint("32", "  +"), ...a);
const warn = (...a) => console.log(paint("33", "  !"), ...a);
const err = (...a) => console.log(paint("31", "  x"), ...a);
const step = (s) => console.log(paint("36", "\n==> " + s));

function ensureDir(p) {
  fs.mkdirSync(p, { recursive: true });
}
function ensureDirs() {
  [BASE, APP, NODE_SRC, CERTS, DATA, LOGS, TMPD].forEach(ensureDir);
}
function rmrf(p) {
  try {
    fs.rmSync(p, { recursive: true, force: true });
  } catch (e) {}
}
function exists(p) {
  try {
    fs.accessSync(p);
    return true;
  } catch (e) {
    return false;
  }
}
function randomToken(n) {
  const chars = "abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  const b = crypto.randomBytes(n);
  let s = "";
  for (let i = 0; i < n; i++) s += chars[b[i] % chars.length];
  return s;
}
function readState() {
  try {
    return JSON.parse(fs.readFileSync(STATE_FILE, "utf8"));
  } catch (e) {
    return {};
  }
}
function saveState(patch) {
  const s = Object.assign(readState(), patch);
  try {
    fs.writeFileSync(STATE_FILE, JSON.stringify(s, null, 2));
  } catch (e) {}
  return s;
}
function portOpen(port, timeout = 800) {
  return new Promise((resolve) => {
    const s = net.connect({ host: "127.0.0.1", port });
    let done = false;
    const fin = (v) => {
      if (done) return;
      done = true;
      try {
        s.destroy();
      } catch (e) {}
      resolve(v);
    };
    s.setTimeout(timeout);
    s.once("connect", () => fin(true));
    s.once("timeout", () => fin(false));
    s.once("error", () => fin(false));
  });
}
function isPortFree(port) {
  return new Promise((resolve) => {
    const s = net.createServer();
    s.once("error", () => resolve(false));
    s.once("listening", () => {
      s.close(() => resolve(true));
    });
    try {
      s.listen(port, "0.0.0.0");
    } catch (e) {
      resolve(false);
    }
  });
}

/* --------------------------- child processes ---------------------- */

const children = new Map();

function killTree(child) {
  if (!child || child.killed) return;
  try {
    process.kill(-child.pid, "SIGTERM");
  } catch (e) {
    try {
      child.kill("SIGTERM");
    } catch (e2) {}
  }
  setTimeout(() => {
    try {
      process.kill(-child.pid, "SIGKILL");
    } catch (e) {}
  }, 4000);
}

function openLog(name) {
  try {
    return fs.createWriteStream(path.join(LOGS, name + ".log"), {
      flags: "a",
    });
  } catch (e) {
    return null;
  }
}

function spawnLogged(cmd, args, opts, name, label) {
  const out = openLog(name);
  const child = spawn(cmd, args, Object.assign({}, opts, { detached: true }));
  children.set(name, child);
  const feed = (stream, isErr) => {
    if (!stream) return;
    stream.on("data", (buf) => {
      if (out) {
        try {
          out.write(buf);
        } catch (e) {}
      }
      const text = buf.toString();
      const prefix = paint(isErr ? "31" : "90", "[" + label + "]");
      for (const line of text.split(/\r?\n/)) {
        if (!line.trim()) continue;
        console.log(prefix, line);
      }
    });
  };
  feed(child.stdout, false);
  feed(child.stderr, true);
  child.on("exit", (code, sig) => {
    log(label, "exited", code === null ? sig : code);
  });
  child.on("error", (e) => err(label, e.message));
  return child;
}

function run(cmd, args, opts) {
  opts = opts || {};
  return new Promise((resolve) => {
    const child = spawn(cmd, args, {
      cwd: opts.cwd,
      env: Object.assign({}, process.env, opts.env || {}),
    });
    let out = "",
      errOut = "";
    let beat = null;
    if (opts.heartbeat && opts.heartbeat > 0) {
      const t0 = Date.now();
      beat = setInterval(() => {
        const sec = Math.round((Date.now() - t0) / 1000);
        if (opts.heartbeatLabel) log(opts.heartbeatLabel, sec + "s elapsed");
        else process.stdout.write(".");
      }, opts.heartbeat);
    }
    child.stdout.on("data", (d) => {
      out += d.toString();
      if (opts.echo) process.stdout.write(d);
    });
    child.stderr.on("data", (d) => {
      errOut += d.toString();
      if (opts.echo) process.stderr.write(d);
    });
    const timer = opts.timeout
      ? setTimeout(() => {
          try {
            child.kill("SIGKILL");
          } catch (e) {}
        }, opts.timeout)
      : null;
    child.on("close", (code) => {
      if (timer) clearTimeout(timer);
      if (beat) clearInterval(beat);
      resolve({ code, out, err: errOut });
    });
    child.on("error", (e) => {
      if (timer) clearTimeout(timer);
      if (beat) clearInterval(beat);
      resolve({ code: -1, out, err: String(e.message || e) });
    });
  });
}

/* ---------------------------- networking -------------------------- */

function request(urlStr, opts) {
  opts = opts || {};
  return new Promise((resolve, reject) => {
    let u;
    try {
      u = new URL(urlStr);
    } catch (e) {
      return reject(e);
    }
    const mod = u.protocol === "http:" ? http : require("https");
    const req = mod.request(
      {
        method: opts.method || "GET",
        hostname: u.hostname,
        port: u.port || (u.protocol === "http:" ? 80 : 443),
        path: u.pathname + (u.search || ""),
        headers: Object.assign(
          {
            "User-Agent": UA,
            Accept: "*/*",
            "Accept-Encoding": "identity",
          },
          opts.headers || {}
        ),
        timeout: opts.timeout || 30000,
      },
      (res) => {
        if (
          opts.follow !== false &&
          [301, 302, 303, 307, 308].includes(res.statusCode) &&
          res.headers.location
        ) {
          res.resume();
          const next = new URL(res.headers.location, u).toString();
          return resolve(
            request(next, Object.assign({}, opts, { redirects: (opts.redirects || 0) + 1 }))
          );
        }
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status: res.statusCode,
            headers: res.headers,
            body: Buffer.concat(chunks),
            text: () => Buffer.concat(chunks).toString(),
          })
        );
      }
    );
    req.on("timeout", () => {
      req.destroy(new Error("timeout"));
    });
    req.on("error", reject);
    if (opts.body) req.write(opts.body);
    req.end();
  });
}

async function downloadFile(url, dest, label) {
  const part = dest + ".part";
  await new Promise((resolve, reject) => {
    let u;
    try {
      u = new URL(url);
    } catch (e) {
      return reject(e);
    }
    const mod = u.protocol === "http:" ? http : require("https");
    const req = mod.request(
      {
        method: "GET",
        hostname: u.hostname,
        port: u.port || (u.protocol === "http:" ? 80 : 443),
        path: u.pathname + (u.search || ""),
        headers: { "User-Agent": UA, Accept: "*/*" },
        timeout: 120000,
      },
      (res) => {
        if (
          [301, 302, 303, 307, 308].includes(res.statusCode) &&
          res.headers.location
        ) {
          res.resume();
          const next = new URL(res.headers.location, u).toString();
          return downloadFile(next, dest, label).then(resolve, reject);
        }
        if (res.statusCode !== 200) {
          res.resume();
          return reject(new Error("HTTP " + res.statusCode + " for " + url));
        }
        const total = parseInt(res.headers["content-length"] || "0", 10);
        let got = 0,
          lastTick = 0;
        const out = fs.createWriteStream(part);
        res.on("data", (c) => {
          got += c.length;
          const now = Date.now();
          if (label && now - lastTick > 3000) {
            lastTick = now;
            const pct = total ? " (" + Math.round((got / total) * 100) + "%)" : "";
            process.stdout.write(
              "\r  .. " + label + " " + mb(got) + pct + "      "
            );
          }
        });
        res.pipe(out);
        out.on("finish", () => {
          if (label) process.stdout.write("\r" + " ".repeat(60) + "\r");
          try {
            fs.renameSync(part, dest);
          } catch (e) {
            return reject(e);
          }
          resolve();
        });
        out.on("error", reject);
      }
    );
    req.on("timeout", () => req.destroy(new Error("timeout")));
    req.on("error", reject);
    req.end();
  });
  return dest;
}

function mb(n) {
  if (n > 1024 * 1024) return (n / 1024 / 1024).toFixed(1) + " MB";
  return Math.round(n / 1024) + " KB";
}

/* --------------------------- tar / zip ---------------------------- */

function cstr(buf, start, len) {
  let end = start;
  const max = start + len;
  while (end < max && buf[end] !== 0) end++;
  return buf.toString("utf8", start, end);
}
function octal(buf, start, len) {
  const s = cstr(buf, start, len).trim().replace(/\0/g, "");
  if (!s) return 0;
  const n = parseInt(s, 8);
  return Number.isFinite(n) ? n : 0;
}
function safeJoin(destDir, rel) {
  const target = path.resolve(destDir, rel);
  if (target !== destDir && !target.startsWith(destDir + path.sep)) return null;
  return target;
}

/** Streaming tar.gz extractor (ustar + pax + gnu long names). */
function extractTarGz(gzPath, destDir, strip) {
  strip = strip || 0;
  ensureDir(destDir);
  const pad = (n) => (512 - (n % 512)) % 512;
  return new Promise((resolve, reject) => {
    const rs = fs.createReadStream(gzPath);
    const gunzip = zlib.createGunzip();
    let pending = Buffer.alloc(0);
    let left = 0;            // bytes left for the current entry / padding
    let writing = false;     // are those bytes file content?
    let fd = null;
    let nextPad = 0;
    let longName = null;
    let paxPath = null;
    let linkName = null;
    let files = 0;
    let done = false;

    const processBuf = () => {
      for (;;) {
        if (left > 0) {
          if (!pending.length) return;
          const take = Math.min(left, pending.length);
          if (writing && fd !== null) fs.writeSync(fd, pending.subarray(0, take));
          pending = pending.subarray(take);
          left -= take;
          if (left === 0) {
            if (fd !== null) {
              try { fs.closeSync(fd); } catch (e) {}
              fd = null;
            }
            if (writing) {
              writing = false;
              left = nextPad;
              nextPad = 0;
            }
          }
          continue;
        }
        if (pending.length < 512) return;
        const header = pending.subarray(0, 512);
        let allZero = true;
        for (let i = 0; i < 512; i++) {
          if (header[i] !== 0) { allZero = false; break; }
        }
        pending = pending.subarray(512);
        if (allZero) continue;

        const size = octal(header, 124, 12);
        const type = header[156] ? String.fromCharCode(header[156]) : "0";
        const prefix = cstr(header, 345, 155);
        let name = cstr(header, 0, 100);
        if (prefix) name = prefix + "/" + name;
        const mode = octal(header, 100, 8) || 0o644;

        if (type === "L") {
          longName = size ? pending.toString("utf8", 0, size).replace(/\0+$/, "") : "";
          left = Math.ceil(size / 512) * 512;
          continue;
        }
        if (type === "x" || type === "g") {
          const body = size ? pending.toString("utf8", 0, size) : "";
          const m = body.match(/(?:^|\n)\d+ path=([^\n]*)\n/);
          if (m) paxPath = m[1];
          const lm = body.match(/(?:^|\n)\d+ linkpath=([^\n]*)\n/);
          if (lm) linkName = lm[1];
          left = Math.ceil(size / 512) * 512;
          continue;
        }
        if (longName) { name = longName; longName = null; }
        if (paxPath) { name = paxPath; paxPath = null; }
        const link = linkName || cstr(header, 157, 100);
        linkName = null;

        const parts = name.split("/").filter((x) => x && x !== ".");
        const rel = parts.slice(strip).join("/");
        const dest = rel ? safeJoin(destDir, rel) : null;

        if (!rel || type === "5" || name.endsWith("/")) {
          if (dest && (type === "5" || name.endsWith("/"))) ensureDir(dest);
          writing = false;
          nextPad = 0;
          left = Math.ceil(size / 512) * 512;
          continue;
        }
        if (type === "2" && dest) {
          /* symlink (cpython ships bin/python3 -> python3.12) */
          try {
            try { fs.unlinkSync(dest); } catch (e) {}
            fs.symlinkSync(link, dest);
          } catch (e) {}
          writing = false;
          nextPad = 0;
          left = Math.ceil(size / 512) * 512;
          continue;
        }
        if (!dest || type === "1" || type === "3") {
          writing = false;
          nextPad = 0;
          left = Math.ceil(size / 512) * 512;
          continue;
        }
        ensureDir(path.dirname(dest));
        try {
          fd = fs.openSync(dest, "w", mode & 0o777);
        } catch (e) {
          fd = null;
        }
        files++;
        writing = true;
        nextPad = pad(size);
        left = size;
        if (left === 0 && fd !== null) {
          try { fs.closeSync(fd); } catch (e) {}
          fd = null;
          writing = false;
          left = nextPad;
          nextPad = 0;
        }
      }
    };

    rs.on("error", reject);
    gunzip.on("error", reject);
    rs.pipe(gunzip);
    gunzip.on("data", (chunk) => {
      if (done) return;
      pending = pending.length ? Buffer.concat([pending, chunk]) : chunk;
      try {
        processBuf();
      } catch (e) {
        done = true;
        reject(e);
      }
    });
    gunzip.on("end", () => {
      done = true;
      if (fd !== null) {
        try { fs.closeSync(fd); } catch (e) {}
      }
      resolve(files);
    });
  });
}

/** Minimal zip extractor for the files we care about. */
function extractZip(zipPath, destDir, wanted) {
  ensureDir(destDir);
  const buf = fs.readFileSync(zipPath);
  let eocd = -1;
  for (let i = buf.length - 22; i >= 0 && i > buf.length - 70000; i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) {
      eocd = i;
      break;
    }
  }
  if (eocd < 0) throw new Error("not a zip file");
  const count = buf.readUInt16LE(eocd + 10);
  let off = buf.readUInt32LE(eocd + 16);
  const written = [];
  for (let i = 0; i < count; i++) {
    if (buf.readUInt32LE(off) !== 0x02014b50) break;
    const method = buf.readUInt16LE(off + 10);
    const compSize = buf.readUInt32LE(off + 20);
    const nameLen = buf.readUInt16LE(off + 28);
    const extraLen = buf.readUInt16LE(off + 30);
    const commentLen = buf.readUInt16LE(off + 32);
    const localOff = buf.readUInt32LE(off + 42);
    const name = buf.toString("utf8", off + 46, off + 46 + nameLen);
    off += 46 + nameLen + extraLen + commentLen;
    const base = path.basename(name);
    if (wanted && !wanted.includes(base)) continue;
    if (name.endsWith("/")) continue;
    const lNameLen = buf.readUInt16LE(localOff + 26);
    const lExtraLen = buf.readUInt16LE(localOff + 28);
    const dataStart = localOff + 30 + lNameLen + lExtraLen;
    const data = buf.subarray(dataStart, dataStart + compSize);
    const out = method === 0 ? data : zlib.inflateRawSync(data);
    const dest = path.join(destDir, base);
    fs.writeFileSync(dest, out);
    try {
      fs.chmodSync(dest, 0o755);
    } catch (e) {}
    written.push(base);
  }
  return written;
}


