/* ----------------------------- patching --------------------------- */

function patchFile(file, reps) {
  let text;
  try {
    text = fs.readFileSync(file, "utf8");
  } catch (e) {
    return false;
  }
  let changed = false;
  for (const [from, to] of reps) {
    if (text.includes(to)) continue;
    if (!text.includes(from)) continue;
    text = text.split(from).join(to);
    changed = true;
  }
  if (changed) {
    try {
      fs.writeFileSync(file, text);
    } catch (e) {}
  }
  return changed;
}

function patchPanel() {
  const grpcPatch = [
    [
      "from .grpcio import MarzNodeGRPCIO\n",
      "try:  # KataBump: grpcio is optional, we ship grpclib only\n" +
        "    from .grpcio import MarzNodeGRPCIO\n" +
        "except Exception:  # pragma: no cover\n" +
        "    MarzNodeGRPCIO = None\n",
    ],
  ];
  patchFile(path.join(APP, "app", "marznode", "__init__.py"), grpcPatch);
  patchFile(
    path.join(APP, "app", "marznode", "operations.py"),
    grpcPatch.concat([
      [
        "    if db_node.connection_backend == NodeConnectionBackend.grpcio:\n",
        "    if (\n        db_node.connection_backend == NodeConnectionBackend.grpcio\n        and MarzNodeGRPCIO is not None\n    ):\n",
      ],
    ])
  );

  /* aiogram + aiohttp are only needed for notifications; import them lazily so
     the panel process stays ~110 MB smaller on a 308 MB box. */
  patchFile(path.join(APP, "app", "notification", "services.py"), [
    [
      "from app.notification import telegram, webhook",
      "# KataBump: notification channels are imported lazily (RAM budget)",
    ],
    [
      "        await webhook.send_notification(message)",
      "        from app.notification import webhook  # KataBump: lazy\n\n" +
        "        await webhook.send_notification(message)",
    ],
    [
      "        await telegram.send_notification(message)",
      "        from app.notification import telegram  # KataBump: lazy\n\n" +
        "        await telegram.send_notification(message)",
    ],
  ]);

  /* alpn is a plain Enum in marzneshin -> v2share would render the enum name */
  patchFile(path.join(APP, "app", "utils", "share.py"), [
    [
      'alpn=host.alpn if host.alpn != "none" else None,',
      'alpn=(host.alpn.value if hasattr(host.alpn, "value") else host.alpn)\n'
        + '        if str(getattr(host.alpn, "value", host.alpn)) != "none"\n'
        + "        else None,",
    ],
  ]);
}

function patchNode() {
  patchFile(path.join(NODE_SRC, "marznode", "marznode.py"), [
    [
      "from marznode.backends.hysteria2.hysteria2_backend import HysteriaBackend\n" +
        "from marznode.backends.singbox.singbox_backend import SingBoxBackend\n",
      "# KataBump: hysteria2 / sing-box backends are imported lazily (RAM budget)\n",
    ],
    [
      "    if HYSTERIA_ENABLED:\n        hysteria_backend = HysteriaBackend(",
      "    if HYSTERIA_ENABLED:\n" +
        "        from marznode.backends.hysteria2.hysteria2_backend import (\n" +
        "            HysteriaBackend,\n        )\n\n" +
        "        hysteria_backend = HysteriaBackend(",
    ],
    [
      "    if SING_BOX_ENABLED:\n        sing_box_backend = SingBoxBackend(",
      "    if SING_BOX_ENABLED:\n" +
        "        from marznode.backends.singbox.singbox_backend import (\n" +
        "            SingBoxBackend,\n        )\n\n" +
        "        sing_box_backend = SingBoxBackend(",
    ],
  ]);
}

/* ------------------------------- venv ----------------------------- */
/*  KataBump's system Python is a stripped Debian build: `python -m venv`
 *  creates the interpreter but NOT pip (ensurepip was removed).  The old
 *  wrapper assumed pip existed and died with:
 *      /home/container/marzneshin/venv/bin/python: No module named pip
 *  Because the public port stayed open, that error looked like a 20-minute
 *  freeze.  This version never depends on ensurepip:
 *      1. create the venv with --without-pip (works everywhere)
 *      2. try ensurepip, then get-pip.py
 *      3. otherwise run pip from the standalone pip.pyz zipapp
 *         (a zipapp needs no installed pip at all)
 *      4. as a last resort install a portable CPython that ships pip
 * ------------------------------------------------------------------- */

const PIP_PYZ_URL =
  process.env.MZ_PIP_PYZ_URL || "https://bootstrap.pypa.io/pip/pip.pyz";
const GET_PIP_URL =
  process.env.MZ_GET_PIP_URL || "https://bootstrap.pypa.io/get-pip.py";

function reqsHash() {
  return crypto
    .createHash("sha1")
    .update(PY_REQS.join("\n") + "|v5-katabump")
    .digest("hex")
    .slice(0, 16);
}

function venvPython() {
  return path.join(VENV, "bin", "python");
}

async function pipWorks(exe) {
  const r = await run(exe, ["-m", "pip", "--version"], { timeout: 60000 });
  return r.code === 0 && /^pip\s/i.test((r.out || "").trim());
}

async function createVenv(py) {
  const exe = venvPython();
  if (exists(exe)) return exe;
  rmrf(VENV);
  let last = "";
  for (const args of [
    ["-m", "venv", "--without-pip", VENV],
    ["-m", "venv", VENV],
  ]) {
    const r = await run(py, args, { timeout: 240000 });
    if (exists(exe)) return exe;
    last = ((r.err || "") + "\n" + (r.out || "")).trim().slice(-400);
  }
  const vv = await run(py, ["-m", "virtualenv", "--no-download", VENV], {
    timeout: 300000,
  });
  if (exists(exe)) return exe;
  throw new Error(
    "could not create a virtualenv (no venv/virtualenv module): " +
      (last || (vv.err || "").slice(-300))
  );
}

async function bootstrapPip(py, exe) {
  if (await pipWorks(exe)) return { argv: ["-m", "pip"], file: "" };

  /* MZ_SKIP_ENSUREPIP=1 simulates KataBump's stripped python; handy for tests */
  const skip = process.env.MZ_SKIP_ENSUREPIP === "1";

  /* 1 - ensurepip (present on normal pythons, stripped on KataBump) */
  if (!skip) {
    await run(exe, ["-m", "ensurepip", "--upgrade", "--default-pip"], {
      timeout: 300000,
    });
    if (await pipWorks(exe)) return { argv: ["-m", "pip"], file: "" };
    warn("this python has no ensurepip - bootstrapping pip from the internet");
  } else {
    warn("MZ_SKIP_ENSUREPIP=1 - forcing the pip.pyz bootstrap path");
  }

  /* 2 - get-pip.py */
  const getPip = path.join(TMPD, "get-pip.py");
  if (!skip) {
    try {
      await downloadFile(GET_PIP_URL, getPip, "get-pip.py");
      await run(
        exe,
        [getPip, "--no-warn-script-location", "--disable-pip-version-check"],
        { timeout: 420000, heartbeat: 20000, heartbeatLabel: "get-pip.py:" }
      );
      if (await pipWorks(exe)) {
        try { fs.unlinkSync(getPip); } catch (e) {}
        ok("pip installed with get-pip.py");
        return { argv: ["-m", "pip"], file: "" };
      }
    } catch (e) {
      warn("get-pip.py: " + e.message);
    }
  }
  try { fs.unlinkSync(getPip); } catch (e) {}

  /* 3 - pip.pyz: a zipapp, so it runs even in a venv with zero pip */
  const pyz = path.join(TMPD, "pip.pyz");
  try {
    if (!exists(pyz)) await downloadFile(PIP_PYZ_URL, pyz, "pip.pyz");
    const chk = await run(exe, [pyz, "--version"], { timeout: 60000 });
    if (chk.code === 0) {
      ok("pip bootstrapped from pip.pyz");
      return { argv: [pyz], file: pyz };
    }
    warn("pip.pyz did not run: " + (chk.err || chk.out || "").slice(-200));
  } catch (e) {
    warn("pip.pyz: " + e.message);
  }
  return null;
}

async function ensureVenv(sysPy) {
  const marker = path.join(VENV, ".mz-reqs");
  const exe0 = venvPython();
  let need = true;
  if (exists(exe0) && exists(marker)) {
    try {
      need = fs.readFileSync(marker, "utf8").trim() !== reqsHash();
    } catch (e) {
      need = true;
    }
    if (!need) {
      const chk = await run(
        exe0,
        ["-c", "import fastapi,sqlalchemy,uvicorn,alembic,grpclib,v2share;print('ok')"],
        { timeout: 90000 }
      );
      need = chk.code !== 0 || !/ok/.test(chk.out || "");
      if (need) warn("some python packages are missing - reinstalling");
    }
  }
  if (!need) return exe0;

  step("preparing python environment (2-5 min on the first start)");
  let py = sysPy;
  let exe = await createVenv(py);
  let pip = await bootstrapPip(py, exe);

  if (!pip) {
    warn("pip bootstrap failed - installing a portable CPython instead");
    py = await installPortablePython();
    rmrf(VENV);
    exe = await createVenv(py);
    pip = await bootstrapPip(py, exe);
    if (!pip)
      throw new Error("cannot bootstrap pip (no ensurepip, no get-pip.py, no pip.pyz)");
  }

  /* put a real pip inside the venv when we had to use the zipapp */
  if (pip.file) {
    const inst = await run(
      exe,
      pip.argv.concat([
        "install",
        "--no-cache-dir",
        "--disable-pip-version-check",
        "pip",
        "setuptools",
        "wheel",
      ]),
      { timeout: 420000, heartbeat: 20000, heartbeatLabel: "pip bootstrap:" }
    );
    if (inst.code === 0 && (await pipWorks(exe))) {
      try { fs.unlinkSync(pip.file); } catch (e) {}
      pip = { argv: ["-m", "pip"], file: "" };
    } else {
      warn("could not install pip into the venv - using pip.pyz directly");
    }
  } else {
    const up = await run(
      exe,
      [
        "-m",
        "pip",
        "install",
        "-q",
        "--disable-pip-version-check",
        "--upgrade",
        "pip",
        "setuptools",
        "wheel",
      ],
      { timeout: 420000, heartbeat: 20000, heartbeatLabel: "pip upgrade:" }
    );
    if (up.code !== 0)
      warn("pip/setuptools/wheel upgrade failed (continuing anyway)");
  }

  const reqFile = path.join(TMPD, "requirements.txt");
  fs.writeFileSync(reqFile, PY_REQS.join("\n") + "\n");
  log("installing " + PY_REQS.length + " python packages ...");
  let r = await run(
    exe,
    pip.argv.concat([
      "install",
      "--no-cache-dir",
      "--prefer-binary",
      "--disable-pip-version-check",
      "-r",
      reqFile,
    ]),
    {
      timeout: 1200000,
      echo: false,
      heartbeat: 20000,
      heartbeatLabel: "pip install (working)",
    }
  );
  if (r.code !== 0) {
    warn("first pip pass failed - retrying without --prefer-binary");
    err((r.err || r.out || "").slice(-1200));
    r = await run(
      exe,
      pip.argv.concat([
        "install",
        "--no-cache-dir",
        "--disable-pip-version-check",
        "-r",
        reqFile,
      ]),
      {
        timeout: 1200000,
        echo: false,
        heartbeat: 20000,
        heartbeatLabel: "pip install retry (working)",
      }
    );
  }
  if (r.code !== 0) {
    err((r.err || "").slice(-2000) || (r.out || "").slice(-2000));
    throw new Error(
      "pip install failed (exit " + r.code + ") - see marzneshin/ERROR.txt"
    );
  }
  try { fs.writeFileSync(marker, reqsHash()); } catch (e) {}
  if (pip.file) {
    try { fs.unlinkSync(pip.file); } catch (e) {}
  }
  ok("python packages installed");
  return exe;
}

