/* ------------------------------ xray ------------------------------ */

function xrayBinary() {
  return path.join(XRAY, "xray");
}

function xrayReady() {
  return exists(xrayBinary());
}

async function installXray(force) {
  if (!force && xrayReady()) return;
  step("downloading Xray-core " + XRAY_VERSION);
  const arch = process.arch === "arm64" ? "arm64-v8a" : "64";
  const zip = "Xray-linux-" + arch + ".zip";
  const url =
    "https://github.com/XTLS/Xray-core/releases/download/" +
    XRAY_VERSION +
    "/" +
    zip;
  const dest = path.join(TMPD, "xray.zip");
  await downloadFile(url, dest, "xray-core");
  ensureDir(XRAY);
  extractZip(dest, XRAY, ["xray", "geoip.dat", "geosite.dat", "LICENSE", "README.md"]);
  try {
    fs.unlinkSync(dest);
  } catch (e) {}
  try {
    fs.chmodSync(xrayBinary(), 0o755);
  } catch (e) {}
  const v = spawnSync(xrayBinary(), ["version"]);
  ok("xray ready " + (v.stdout ? String(v.stdout).split("\n")[0] : ""));
}

function xrayKeys() {
  const st = readState();
  if (st.realityPrivateKey && st.realityPublicKey) return st;
  const r = spawnSync(xrayBinary(), ["x25519"], { encoding: "utf8" });
  const out = (r.stdout || "") + (r.stderr || "");
  const priv =
    (out.match(/(?:Private key|PrivateKey)\s*:\s*([A-Za-z0-9_\-]+)/) || [])[1] || "";
  const pub =
    (out.match(
      /(?:Public key|PublicKey|Password(?: \(PublicKey\))?)\s*:\s*([A-Za-z0-9_\-]+)/
    ) || [])[1] || "";
  if (!priv || !pub) throw new Error("could not parse xray x25519 output: " + out);
  return saveState({ realityPrivateKey: priv, realityPublicKey: pub });
}

/* ------------------------- ports & xray config -------------------- */

async function assignPorts() {
  const st = readState();
  const prev = st.ports || {};
  const keys = ["reality", "vless_ws", "vmess_ws", "trojan_ws", "upgrade", "grpc", "ss"];
  const defaults = {
    reality: 20001,
    vless_ws: 20002,
    vmess_ws: 20003,
    trojan_ws: 20004,
    upgrade: 20005,
    grpc: 20006,
    ss: 20007,
  };
  const used = new Set([PUBLIC_PORT]);
  const takePort = async (start) => {
    let p = start;
    while (p < 64000 && (used.has(p) || !(await isPortFree(p)))) p++;
    used.add(p);
    return p;
  };
  const out = {};
  for (const k of keys) {
    out[k] = await takePort(int(prev[k], 0) || defaults[k]);
  }
  const panel = await takePort(int(st.panelPort, 0) || 8001);
  const node = await takePort(int(st.nodePort, 0) || 53042);
  saveState({ ports: out, panelPort: panel, nodePort: node });
  return Object.assign({ panel, node }, out);
}

function buildXrayConfig(ports) {
  const st = readState();
  const sniList = []
    .concat([REALITY_SNI], REALITY_SNI_ALT, OPERATORS.map((o) => o.sni))
    .filter((v, i, a) => v && a.indexOf(v) === i);
  const sid =
    st.shortId || saveState({ shortId: crypto.randomBytes(4).toString("hex") }).shortId;
  const ssPass = st.ssPassword || saveState({ ssPassword: randomToken(24) }).ssPassword;

  const inbounds = [
    {
      tag: "VLESS-REALITY",
      listen: "127.0.0.1",
      port: ports.reality,
      protocol: "vless",
      settings: { clients: [], decryption: "none" },
      streamSettings: {
        network: "tcp",
        security: "reality",
        realitySettings: {
          show: false,
          dest: REALITY_SNI + ":443",
          xver: 0,
          serverNames: sniList,
          privateKey: readState().realityPrivateKey,
          shortIds: [sid],
        },
      },
      sniffing: { enabled: true, destOverride: ["http", "tls", "quic"], routeOnly: false },
    },
    {
      tag: "VLESS-WS",
      listen: "127.0.0.1",
      port: ports.vless_ws,
      protocol: "vless",
      settings: { clients: [], decryption: "none" },
      streamSettings: {
        network: "ws",
        security: "none",
        wsSettings: { path: P.ws_vless, headers: {} },
      },
    },
    {
      tag: "VMESS-WS",
      listen: "127.0.0.1",
      port: ports.vmess_ws,
      protocol: "vmess",
      settings: { clients: [] },
      streamSettings: {
        network: "ws",
        security: "none",
        wsSettings: { path: P.ws_vmess, headers: {} },
      },
    },
    {
      tag: "TROJAN-WS",
      listen: "127.0.0.1",
      port: ports.trojan_ws,
      protocol: "trojan",
      settings: { clients: [] },
      streamSettings: {
        network: "ws",
        security: "none",
        wsSettings: { path: P.ws_trojan, headers: {} },
      },
    },
    {
      tag: "VLESS-HTTPUPGRADE",
      listen: "127.0.0.1",
      port: ports.upgrade,
      protocol: "vless",
      settings: { clients: [], decryption: "none" },
      streamSettings: {
        network: "httpupgrade",
        security: "none",
        httpupgradeSettings: { path: P.upgrade, host: "" },
      },
    },
    {
      tag: "VLESS-GRPC",
      listen: "127.0.0.1",
      port: ports.grpc,
      protocol: "vless",
      settings: { clients: [], decryption: "none" },
      streamSettings: {
        network: "grpc",
        security: "none",
        grpcSettings: { serviceName: P.grpc, multiMode: false },
      },
    },
    {
      tag: "SHADOWSOCKS",
      listen: "127.0.0.1",
      port: ports.ss,
      protocol: "shadowsocks",
      settings: {
        method: "chacha20-ietf-poly1305",
        password: ssPass,
        network: "tcp",
      },
    },
  ];

  const cfg = {
    log: { loglevel: "warning" },
    inbounds,
    outbounds: [
      { protocol: "freedom", tag: "direct", settings: { domainStrategy: "UseIP" } },
      { protocol: "blackhole", tag: "block" },
    ],
    routing: {
      domainStrategy: "AsIs",
      rules: [
        { type: "field", ip: ["geoip:private"], outboundTag: "block" },
        { type: "field", protocol: ["bittorrent"], outboundTag: "block" },
      ],
    },
    policy: {
      levels: { "0": { statsUserUplink: true, statsUserDownlink: true } },
      system: {
        statsInboundUplink: false,
        statsInboundDownlink: false,
        statsOutboundUplink: true,
        statsOutboundDownlink: true,
      },
    },
  };
  fs.writeFileSync(XRAY_CONFIG, JSON.stringify(cfg, null, 2));
  return cfg;
}

