/* -------------------------- database setup ------------------------ */

function pyEnv() {
  return {
    PYTHONUNBUFFERED: "1",
    PYTHONDONTWRITEBYTECODE: "1",
    MALLOC_ARENA_MAX: "2",
    MALLOC_TRIM_THRESHOLD_: "65536",
    UVICORN_HOST: "127.0.0.1",
    UVICORN_PORT: String(PORT_ENV.panel),
    DASHBOARD_PATH: PANEL_MOUNT,
    SQLALCHEMY_DATABASE_URL: DB_URL,
    SUBSCRIPTION_URL_PREFIX: publicHost()
      ? "http://" + publicHost() + ":" + PUBLIC_PORT
      : "",
    AUTH_GENERATION_ALGORITHM: "xxh128",
  };
}

async function migrate(py) {
  step("applying database migrations");
  const r = await run(py, ["-m", "alembic", "upgrade", "head"], {
    cwd: APP,
    env: pyEnv(),
    timeout: 300000,
  });
  if (r.code !== 0) {
    err((r.err || r.out).slice(-1500));
    throw new Error("migration failed");
  }
  ok("database ready");
}

async function exportClientCert(py) {
  const certPath = path.join(CERTS, "client.crt");
  if (exists(certPath)) return;
  const code =
    "from app.db import GetDB, get_tls_certificate\n" +
    "with GetDB() as db:\n" +
    "    c = get_tls_certificate(db)\n" +
    "    open(" + JSON.stringify(certPath) + ", 'w').write(c.certificate)\n";
  const r = await run(py, ["-c", code], { cwd: APP, env: pyEnv(), timeout: 120000 });
  if (r.code !== 0 || !exists(path.join(CERTS, "client.crt"))) {
    err((r.err || r.out).slice(-800));
    throw new Error("could not export the panel client certificate");
  }
  ok("panel certificate exported for the node");
}

async function ensureAdmin(py) {
  const st = readState();
  const pass = ADMIN_PASS_ENV || st.adminPass || randomToken(14);
  if (!st.adminPass && !ADMIN_PASS_ENV) saveState({ adminPass: pass, adminUser: ADMIN_USER });
  const r = await run(
    py,
    [
      "marzneshin-cli.py",
      "admin",
      "create",
      "--username",
      ADMIN_USER,
      "--sudo",
      "--password",
      pass,
    ],
    { cwd: APP, env: pyEnv(), timeout: 120000 }
  );
  const txt = (r.out || "") + (r.err || "");
  if (r.code === 0) ok("admin account created: " + ADMIN_USER);
  else if (/already exists/i.test(txt)) ok("admin account already exists: " + ADMIN_USER);
  else warn("admin creation: " + txt.trim().split("\n").slice(-2).join(" "));
  return { user: ADMIN_USER, pass };
}


