async function serveConfigs(client, clean, decision) {
  if (CONFIGS_TOKEN) {
    const q = ((decision && decision.raw) || "").split("?")[1] || "";
    let key = "";
    try { key = new URLSearchParams(q).get("key") || ""; } catch (e) {}
    if (key !== CONFIGS_TOKEN)
      return writeResponse(client, 403, "forbidden: add ?key=...", "text/plain; charset=utf-8");
  }
  if (!READY.profiles.length) loadReady();
  const base = baseUrl();
  const rel =
    clean === CONFIGS_PATH || clean === CONFIGS_PATH + "/"
      ? ""
      : clean.slice(CONFIGS_PATH.length).replace(/^\/+/, "").replace(/\/+$/, "");

  if (rel === "" || rel === "index.html")
    return writeResponse(client, 200, configsHtml(), "text/html; charset=utf-8");
  if (rel === "refresh") {
    const okk = await refreshReadyLinks(PY_BIN, true);
    return writeResponse(
      client,
      200,
      JSON.stringify({ ok: okk, links: READY.links.length, error: READY.error }, null, 2),
      "application/json; charset=utf-8"
    );
  }
  if (rel === "json" || rel === "status.json")
    return writeResponse(
      client,
      200,
      JSON.stringify(
        {
          host: publicHost(),
          port: PUBLIC_PORT,
          updatedAt: READY.updatedAt,
          protocols: READY.links.length,
          profiles: READY.profiles.map((p) => ({
            id: p.id,
            label: p.label,
            sni: p.sni,
            url: p.url,
            txt: p.txt,
            links: p.links,
          })),
          subscription: readState().demoSubUrl || "",
        },
        null,
        2
      ),
      "application/json; charset=utf-8"
    );

  const formats = {
    v2ray: "v2ray",
    links: "links",
    clash: "clash",
    "clash-meta": "clash-meta",
    "sing-box": "sing-box",
    xray: "xray",
  };
  if (formats[rel]) {
    const p = subPath("/" + formats[rel]);
    if (!p)
      return writeResponse(client, 503, "subscription not ready yet", "text/plain; charset=utf-8");
    try {
      const r = await request(panelBase() + p, { timeout: 30000, follow: false });
      const cts = {
        v2ray: "text/plain; charset=utf-8",
        links: "text/plain; charset=utf-8",
        clash: "text/yaml; charset=utf-8",
        "clash-meta": "text/yaml; charset=utf-8",
        "sing-box": "application/json; charset=utf-8",
        xray: "application/json; charset=utf-8",
      };
      return writeResponse(client, r.status, r.body, cts[rel], {
        "Subscription-Userinfo": "upload=0; download=0; total=0; expire=0",
        "Profile-Update-Interval": "1",
      });
    } catch (e) {
      return writeResponse(client, 502, "panel unavailable: " + e.message, "text/plain; charset=utf-8");
    }
  }

  const m = /^([a-z0-9_-]+)(\.txt|\.sub|\.json)?$/i.exec(rel);
  if (m) {
    const prof = READY.profiles.filter((p) => p.id === m[1])[0];
    if (!prof) return writeResponse(client, 404, "unknown profile", "text/plain; charset=utf-8");
    if (m[2] === ".json")
      return writeResponse(
        client,
        200,
        JSON.stringify({ id: prof.id, label: prof.label, links: prof.links }, null, 2),
        "application/json; charset=utf-8"
      );
    if (m[2] === ".txt")
      return writeResponse(
        client,
        200,
        prof.links.join("\n") + "\n",
        "text/plain; charset=utf-8",
        { "Content-Disposition": 'attachment; filename="' + prof.id + '.txt"' }
      );
    return writeResponse(
      client,
      200,
      prof.bundle,
      "text/plain; charset=utf-8",
      {
        "Content-Disposition": 'attachment; filename="' + prof.id + '"',
        "Subscription-Userinfo": "upload=0; download=0; total=0; expire=0",
        "Profile-Update-Interval": "1",
        "Profile-Title": "base64:" + b64s("Marzneshin-" + prof.en),
      }
    );
  }
  return writeResponse(client, 404, "not found", "text/plain; charset=utf-8");
}

/* --------------------------- the mux ------------------------------ */

const METHODS = ["GET", "POST", "HEAD", "PUT", "DELETE", "OPTIONS", "PATCH", "CONNECT", "TRACE"];

function classify(buf) {
  if (buf.length >= 3 && buf[0] === 0x16 && buf[1] === 0x03) return { kind: "tls" };
  if (buf.length >= 4 && buf.toString("latin1", 0, 4) === "PRI ") return { kind: "h2" };
  const slice = buf.toString("latin1", 0, Math.min(buf.length, 600));
  const eol = slice.indexOf("\r\n");
  const line = eol >= 0 ? slice.slice(0, eol) : slice;
  const m = /^([A-Z]+) (\S+)/.exec(line);
  if (m && METHODS.includes(m[1]))
    return { kind: "http", path: m[2].split("?")[0], raw: m[2] };
  if (eol < 0 && buf.length < 600) {
    /* still could be a split request line - wait for more bytes */
    if (METHODS.some((mm) => mm.startsWith(line) || line.startsWith(mm + " ")))
      return null;
    if (line.length < 4) return null;
  }
  return { kind: "binary" };
}

function tunnelPort(clean) {
  if (clean === P.ws_vless || clean.startsWith(P.ws_vless + "/"))
    return { port: PORT_ENV["vless_ws"], name: "vless-ws" };
  if (clean === P.ws_vmess || clean.startsWith(P.ws_vmess + "/"))
    return { port: PORT_ENV["vmess_ws"], name: "vmess-ws" };
  if (clean === P.ws_trojan || clean.startsWith(P.ws_trojan + "/"))
    return { port: PORT_ENV["trojan_ws"], name: "trojan-ws" };
  if (clean === P.upgrade || clean.startsWith(P.upgrade + "/"))
    return { port: PORT_ENV["upgrade"], name: "httpupgrade" };
  return null;
}

function routeSocket(client, first, decision, ip) {
  const clean = decision.path || "/";

  if (
    decision.kind === "http" &&
    (clean === CONFIGS_PATH ||
      clean === CONFIGS_PATH + "/" ||
      clean.startsWith(CONFIGS_PATH + "/") ||
      clean === CONFIGS_PATH + ".txt" ||
      clean === CONFIGS_PATH + ".json")
  ) {
    let c = clean;
    if (c === CONFIGS_PATH + ".txt") c = CONFIGS_PATH + "/all.txt";
    if (c === CONFIGS_PATH + ".json") c = CONFIGS_PATH + "/json";
    serveConfigs(client, c, decision).catch((e) => {
      writeResponse(client, 500, "configs error: " + e.message, "text/plain; charset=utf-8");
    });
    return;
  }
  if (decision.kind === "http" && clean === STATUS_PATH) {
    return writeResponse(
      client,
      200,
      JSON.stringify(STATE, null, 2),
      "application/json; charset=utf-8"
    );
  }
  if (decision.kind === "http" && (clean === "/" || clean === "")) {
    return writeResponse(client, 302, "redirecting", "text/plain; charset=utf-8", {
      Location: PANEL_MOUNT,
    });
  }

  let target = null;
  let name = "panel";
  if (decision.kind === "tls") {
    target = PORT_ENV.reality;
    name = "reality";
  } else if (decision.kind === "h2") {
    target = PORT_ENV.grpc;
    name = "grpc";
  } else if (decision.kind === "binary") {
    target = PORT_ENV.ss;
    name = "shadowsocks";
  } else {
    const t = tunnelPort(clean);
    if (t) {
      target = t.port;
      name = t.name;
    } else {
      target = PORT_ENV.panel;
    }
  }

  if (name === "panel" && !STATE.panelUp) {
    return writeResponse(client, 503, statusHtml(), "text/html; charset=utf-8");
  }

  const isHttp = decision.kind === "http";
  const upstream = net.connect({ host: "127.0.0.1", port: target }, () => {
    try {
      upstream.setNoDelay(true);
      client.setNoDelay(true);
      upstream.write(isHttp ? withForwarded(first, ip) : first);
      client.pipe(upstream);
      upstream.pipe(client);
    } catch (e) {}
  });
  upstream.on("error", () => {
    if (isHttp) {
      writeResponse(client, 502, "upstream unavailable", "text/plain; charset=utf-8");
    } else {
      try {
        client.destroy();
      } catch (e) {}
    }
  });
  client.on("error", () => {
    try {
      upstream.destroy();
    } catch (e) {}
  });
  upstream.on("close", () => {
    try {
      client.destroy();
    } catch (e) {}
  });
  client.on("close", () => {
    try {
      upstream.destroy();
    } catch (e) {}
  });
}

let publicSrvGlobal = null;
function startPublicServer() {
  if (publicSrvGlobal) return Promise.resolve(publicSrvGlobal);
  return new Promise((resolve, reject) => {
    const srv = net.createServer((client) => {
      client.setNoDelay(true);
      let buf = Buffer.alloc(0);
      let routed = false;
      const onData = (chunk) => {
        if (routed) return;
        buf = buf.length ? Buffer.concat([buf, chunk]) : chunk;
        let decision = null;
        try {
          decision = classify(buf);
        } catch (e) {
          decision = { kind: "binary" };
        }
        if (!decision) return;
        routed = true;
        client.removeListener("data", onData);
        client.pause();
        routeSocket(client, buf, decision, client.remoteAddress || "127.0.0.1");
      };
      client.on("data", onData);
      client.on("error", () => {});
      client.on("end", () => {
        if (!routed) {
          try {
            client.destroy();
          } catch (e) {}
        }
      });
    });
    srv.on("error", (e) => {
      err("public port " + PUBLIC_PORT + ": " + e.message);
      STATE.error = e.message;
      reject(e);
    });
    srv.listen(PUBLIC_PORT, "0.0.0.0", () => {
      publicSrvGlobal = srv;
      ok("public port " + PUBLIC_PORT + " open");
      resolve(srv);
    });
  });
}

/* ------------------------- panel / node API ----------------------- */

function panelBase() {
  return "http://127.0.0.1:" + PORT_ENV.panel;
}

async function api(method, p, body, token) {
  const headers = { Accept: "application/json" };
  let payload = null;
  if (body !== undefined && body !== null) {
    if (typeof body === "string") {
      headers["Content-Type"] = "application/x-www-form-urlencoded";
      payload = body;
    } else {
      headers["Content-Type"] = "application/json";
      payload = JSON.stringify(body);
    }
  }
  if (token) headers.Authorization = "Bearer " + token;
  const r = await request(panelBase() + p, {
    method,
    headers,
    body: payload,
    timeout: 30000,
    follow: false,
  });
  let json = null;
  try {
    json = JSON.parse(r.body.toString());
  } catch (e) {}
  return { status: r.status, json, text: r.body.toString() };
}

async function login() {
  const st = readState();
  const pass = ADMIN_PASS_ENV || st.adminPass;
  if (!pass) return null;
  const body =
    "username=" + encodeURIComponent(ADMIN_USER) + "&password=" + encodeURIComponent(pass);
  const r = await api("POST", "/api/admins/token", body);
  if (r.status === 200 && r.json && r.json.access_token) return r.json.access_token;
  return null;
}

async function waitFor(fn, timeoutMs, everyMs) {
  const t0 = Date.now();
  while (Date.now() - t0 < timeoutMs) {
    try {
      if (await fn()) return true;
    } catch (e) {}
    await sleep(everyMs || 1500);
  }
  return false;
}

async function bootstrapApi() {
  const token = await login();
  if (!token) return false;

  /* node */
  let nodes = await api("GET", "/api/nodes?page=1&size=20", null, token);
  if (nodes.status !== 200) return false;
  if (!nodes.json.items || !nodes.json.items.length) {
    const r = await api(
      "POST",
      "/api/nodes",
      {
        name: "KataBump",
        address: "127.0.0.1",
        port: PORT_ENV.node,
        connection_backend: "grpclib",
        usage_coefficient: 1,
      },
      token
    );
    if (r.status >= 400) warn("creating node: " + (r.text || "").slice(0, 200));
    await sleep(2500);
  }

  /* make sure the node entry matches the ports we actually use */
  const nodeEntry = (nodes.json.items || [])[0];
  if (
    nodeEntry &&
    (nodeEntry.port !== PORT_ENV.node ||
      nodeEntry.address !== "127.0.0.1" ||
      nodeEntry.connection_backend !== "grpclib")
  ) {
    await api(
      "PUT",
      "/api/nodes/" + nodeEntry.id,
      {
        address: "127.0.0.1",
        port: PORT_ENV.node,
        connection_backend: "grpclib",
      },
      token
    );
    await sleep(2500);
  }

  /* inbounds (they appear after the node syncs its xray config) */
  const got = await waitFor(async () => {
    const r = await api("GET", "/api/inbounds?page=1&size=50", null, token);
    return r.status === 200 && r.json && r.json.items && r.json.items.length >= 5;
  }, 120000, 3000);
  if (!got) {
    warn("inbounds did not appear in time (node still syncing)");
    return false;
  }

  const inb = await api("GET", "/api/inbounds?page=1&size=50", null, token);
  const inbounds = inb.json.items || [];
  STATE.inbounds = inbounds.length;

  /* hosts: point them to the public address */
  await fixHosts(token);

  /* one service containing every inbound */
  const svcList = await api("GET", "/api/services?page=1&size=50", null, token);
  let service = (svcList.json.items || [])[0];
  if (!service) {
    const r = await api(
      "POST",
      "/api/services",
      { name: "all", inbound_ids: inbounds.map((i) => i.id) },
      token
    );
    if (r.status >= 400) warn("creating service: " + (r.text || "").slice(0, 200));
    service = r.json;
  }
  if (!service || !service.id) return false;

  /* demo user with a ready-to-use subscription */
  const st = readState();
  if (st.demoCreated !== true) {
    const exist = await api("GET", "/api/users/" + DEMO_USER, null, token);
    if (exist.status !== 200) {
      const r = await api(
        "POST",
        "/api/users",
        {
          username: DEMO_USER,
          service_ids: [service.id],
          expire_strategy: "never",
          data_limit: 0,
          note: "KataBump demo - change or delete me",
        },
        token
      );
      if (r.status >= 400) warn("creating demo user: " + (r.text || "").slice(0, 200));
    }
    saveState({ demoCreated: true, serviceId: service.id });
  }

  const u = await api("GET", "/api/users/" + DEMO_USER, null, token);
  if (u.status === 200) {
    STATE.users = 1;
    saveState({ demoSubUrl: u.json.subscription_url || "" });
    await maybeRefreshLinks(PY_BIN, true);
  }
  return true;
}

async function fixHosts(token) {
  const host = publicHost();
  if (!host) return;
  const r = await api("GET", "/api/inbounds/hosts?page=1&size=100", null, token);
  if (r.status !== 200 || !r.json || !r.json.items) return;
  const st = readState();
  /* when the detected public host changes we re-point every host once */
  const force = st.syncedHostAddress !== host;
  let changed = 0;
  for (const h of r.json.items) {
    const unset = !h.address || h.address.indexOf("{SERVER_IP}") >= 0;
    const badPort = h.port !== PUBLIC_PORT;
    if (!force && !unset && !badPort) continue;
    const body = Object.assign({}, h, {
      address: force || unset ? host : h.address,
      port: PUBLIC_PORT,
    });
    delete body.id;
    delete body.service_ids;
    delete body.protocol;
    delete body.network;
    delete body.noise;
    delete body.chain_ids;
    const w = await api("PUT", "/api/inbounds/hosts/" + h.id, body, token);
    if (w.status === 200) changed++;
    else warn("host " + h.id + " update failed: HTTP " + w.status);
  }
  if (changed) ok("hosts pointed at " + host + ":" + PUBLIC_PORT + " (" + changed + ")");
  if (force) saveState({ syncedHostAddress: host });
}

