/* --------------------------- processes ---------------------------- */

/* children are detached, so a hard restart can leave them behind: clean up */
function killOrphans() {
  const xb = xrayBinary();
  let pids = [];
  try {
    pids = fs.readdirSync("/proc").filter((x) => /^\d+$/.test(x));
  } catch (e) {
    return;
  }
  for (const pid of pids) {
    const n = parseInt(pid, 10);
    if (!n || n === process.pid) continue;
    let cmd = "";
    try {
      cmd = fs.readFileSync("/proc/" + n + "/cmdline", "utf8").replace(/\0/g, " ");
    } catch (e) {
      continue;
    }
    if (!cmd) continue;
    const mine =
      cmd.includes(BASE) &&
      (cmd.includes("marznode.py") || cmd.includes("main.py") || cmd.includes("/venv/bin/"));
    const isXray = xb && cmd.split(" ")[0] === xb;
    if (mine || isXray) {
      try {
        process.kill(n, "SIGKILL");
        log("cleaned up leftover process", n, "(" + cmd.slice(0, 60).trim() + ")");
      } catch (e) {}
    }
  }
}

function procAlive(p) {
  return !!(p && !p.killed && p.exitCode === null && !p.signalCode);
}

function startNode(py) {
  if (procAlive(nodeProc)) return nodeProc;
  log("starting marznode on 127.0.0.1:" + PORT_ENV.node);
  nodeProc = spawnLogged(
    py,
    ["marznode.py"],
    {
      cwd: NODE_SRC,
      env: Object.assign({}, process.env, {
        PYTHONUNBUFFERED: "1",
        PYTHONDONTWRITEBYTECODE: "1",
        MALLOC_ARENA_MAX: "2",
        MALLOC_TRIM_THRESHOLD_: "65536",
      }),
    },
    "node",
    "node"
  );
  return nodeProc;
}

function startPanel(py) {
  if (procAlive(panelProc)) return panelProc;
  log("starting Marzneshin panel on 127.0.0.1:" + PORT_ENV.panel);
  panelProc = spawnLogged(
    py,
    ["main.py"],
    {
      cwd: APP,
      env: Object.assign({}, process.env, pyEnv()),
    },
    "panel",
    "panel"
  );
  return panelProc;
}

async function waitPanelReady(ms) {
  const okk = await waitFor(async () => {
    const r = await api("GET", "/api/admins/token", undefined, undefined);
    return r.status > 0 && r.status < 500;
  }, ms, 1500);
  STATE.panelUp = okk;
  return okk;
}

/* ---------------------------- watchdog ---------------------------- */

let wdRunning = false;
async function watchdog(py) {
  if (wdRunning) return;
  wdRunning = true;
  gcNow();
  const st = readState();
  try {
    if (!procAlive(nodeProc)) {
      warn("node is down - restarting");
      startNode(py);
      await sleep(3000);
    }
    if (!procAlive(panelProc)) {
      warn("panel is down - restarting");
      startPanel(py);
      await sleep(4000);
    }
    STATE.panelUp = await portOpen(PORT_ENV.panel, 1200);
    STATE.nodeUp = await portOpen(PORT_ENV.node, 1200);
    STATE.xrayUp = exists(xrayBinary());

    if (STATE.panelUp && STATE.step !== "ready") {
      STATE.step = "ready";
    }
    if (STATE.panelUp) {
      await maybeRefreshLinks(py, false);
      const token = await login();
      if (token) {
        let done = false;
        const nodes = await api("GET", "/api/nodes?page=1&size=20", null, token);
        if (nodes.status === 200 && nodes.json && (nodes.json.items || []).length) {
          done = true;
        }
        if (!done) {
          await bootstrapApi();
        } else {
          await fixHosts(token);
          const st2 = readState();
          if (!st2.demoSubUrl) await bootstrapApi();
        }
      }
    }
  } catch (e) {
    warn("watchdog: " + e.message);
  } finally {
    wdRunning = false;
    gcNow();
  }
}

/* ------------------------------ main ------------------------------ */

function detectPublicHost() {
  return (async () => {
    if (PUBLIC_HOST_ENV) return PUBLIC_HOST_ENV;
    const st = readState();
    if (st.publicHost) return st.publicHost;
    for (const url of [
      "https://api.ipify.org",
      "https://icanhazip.com",
      "https://ifconfig.io/ip",
      "https://api64.ipify.org",
    ]) {
      try {
        const r = await request(url, { timeout: 8000 });
        const ip = r.body.toString().trim();
        if (/^\d{1,3}(\.\d{1,3}){3}$/.test(ip) || /^[0-9a-f:]+$/i.test(ip)) {
          saveState({ publicHost: ip });
          return ip;
        }
      } catch (e) {}
    }
    return "";
  })();
}

async function main() {
  const t0 = Date.now();
  STATE.error = null;
  STATE.step = "booting";
  console.log(paint("35", "\n  Marzneshin  ·  KataBump Edition"));
  console.log(
    paint("90", "  panel + marznode + xray on a single public port " + PUBLIC_PORT)
  );
  ensureDirs();
  loadReady();
  killOrphans();
  await sleep(900);

  /* decide all internal ports once and keep them stable across restarts */
  PORT_ENV = await assignPorts();
  STATE.panelPort = PORT_ENV.panel;
  STATE.nodePort = PORT_ENV.node;

  /* public listener first, so the URL answers while everything installs */
  let publicSrv = null;
  try {
    publicSrv = await startPublicServer();
  } catch (e) {
    STATE.error = e.message;
    err(
      "cannot bind port " +
        PUBLIC_PORT +
        " - set the SERVER_PORT/PORT env var to the port KataBump gave you"
    );
    process.exit(1);
  }

  const host = await detectPublicHost();
  STATE.publicHost = host;
  saveState({ publicHost: host });
  ok("public host: " + (host || "unknown (set MZ_PUBLIC_HOST)"));

  /* 1. python */
  STATE.step = "python";
  const sysPy = await ensurePython();

  /* 2. panel + dashboard */
  STATE.step = "panel";
  await installPanelSource(false);
  await installDashboard();
  patchPanel();
  patchNode();

  /* 3. python packages */
  STATE.step = "venv";
  if (process.env.MZ_FORCE_SETUP === "1") {
    warn("MZ_FORCE_SETUP=1 - rebuilding the virtualenv");
    rmrf(VENV);
  }
  const py = await ensureVenv(sysPy);
  PY_BIN = py;

  /* 4. marznode + xray */
  STATE.step = "node";
  await installNodeSource(false);
  STATE.step = "xray";
  await installXray(false);
  STATE.xrayUp = true;

  /* 5. configuration */
  STATE.step = "config";
  saveState({
    panelRef: PANEL_REF,
    nodeRef: NODE_REF,
    xrayVersion: XRAY_VERSION,
  });
  xrayKeys();
  buildXrayConfig(PORT_ENV);
  writePanelEnv();
  writeNodeEnv();
  ok("xray config written (" + PORT_ENV.reality + ".." + PORT_ENV.ss + " internal ports)");

  /* 6. database + credentials */
  STATE.step = "database";
  await migrate(py);
  await exportClientCert(py);
  await ensureAdmin(py);

  /* 7. services */
  STATE.step = "services";
  startNode(py);
  const nodeUp = await waitFor(() => portOpen(PORT_ENV.node), 120000, 1500);
  STATE.nodeUp = nodeUp;
  if (!nodeUp) warn("marznode did not open its port yet - continuing");

  startPanel(py);
  const panelUp = await waitPanelReady(300000);
  STATE.panelUp = panelUp;
  if (!panelUp) warn("panel is still starting - the public port keeps answering");

  /* 8. wire everything through the API */
  STATE.step = "bootstrap";
  if (panelUp) {
    const done = await bootstrapApi();
    if (!done) warn("bootstrap incomplete - the watchdog keeps trying");
  }
  STATE.step = panelUp ? "ready" : "starting";
  STATE.inbounds = STATE.inbounds || 0;

  await maybeRefreshLinks(py, false);
  console.log(credsBlock());
  writeCreds();
  ok("ready configs page: " + withKey(baseUrl() + CONFIGS_PATH));

  /* 9. watchdog */
  if (!watchdogTimer) {
    watchdogTimer = setInterval(() => {
      watchdog(py).catch(() => {});
    }, 30000);
  }

  if (!signalsInstalled) {
    signalsInstalled = true;
    const stop = () => {
      log("shutting down");
      try {
        if (publicSrv) publicSrv.close();
      } catch (e) {}
      for (const [, c] of children) killTree(c);
      setTimeout(() => process.exit(0), 800);
    };
    process.on("exit", (c) => log("wrapper exiting with code", c));
    process.on("SIGINT", stop);
    process.on("SIGTERM", stop);
    process.on("uncaughtException", (e) => {
      err("uncaught: " + (e && e.message));
      console.error(e);
    });
    process.on("unhandledRejection", (e) => {
      warn("unhandled: " + (e && e.message));
    });
  }

  log("boot finished in " + Math.round((Date.now() - t0) / 1000) + "s");
}

module.exports = { classify, extractTarGz, extractZip };

/* --------------------------------------------------------------
 *  Prebuilt dashboard (marzneshin dashboard/dist, tar.gz + base64)
 *  -------------------------------------------------------------- */
DASHBOARD_B64 =
  "";

/* ---------------------------- entrypoint -------------------------- */
/*  Placed AFTER the dashboard blob, so DASHBOARD_B64 is assigned
 *  before main() is called.  A failed boot no longer looks like a
 *  freeze: it writes ERROR.txt, logs clearly and retries.           */

async function boot() {
  const max = int(process.env.MZ_BOOT_RETRIES, 3);
  for (let attempt = 1; attempt <= max; attempt++) {
    try {
      await main();
      try { fs.unlinkSync(path.join(BASE, "ERROR.txt")); } catch (e) {}
      return;
    } catch (e) {
      STATE.step = "error";
      STATE.error = e && e.message ? e.message : String(e);
      err("boot attempt " + attempt + "/" + max + " failed: " + STATE.error);
      console.error(e);
      try {
        ensureDir(BASE);
        fs.writeFileSync(
          path.join(BASE, "ERROR.txt"),
          new Date().toISOString() + "\n" + STATE.error + "\n\n" +
            (e && e.stack ? e.stack : "") + "\n\n" +
            "The public port stays up on " + STATUS_PATH + ".\n" +
            "Fix the error above and restart, or set MZ_FORCE_SETUP=1\n" +
            "for one start to rebuild the python virtualenv.\n"
        );
      } catch (x) {}
      if (attempt >= max) {
        err("giving up - see marzneshin/ERROR.txt");
        return;
      }
      const wait = 20000 * attempt;
      log("retrying in " + Math.round(wait / 1000) + "s ...");
      await sleep(wait);
    }
  }
}

if (process.env.MZ_SELFTEST === "1") {
  console.log("selftest: classify checks");
  const t = (buf, want) => {
    const b = Buffer.from(buf, "latin1");
    const d = classify(b);
    console.log((d && d.kind) === want ? "  ok " : "  FAIL ", JSON.stringify(buf.slice(0, 20)), d && d.kind);
  };
  t("\x16\x03\x01\x02\x00", "tls");
  t("GET /dashboard/ HTTP/1.1\r\nHost: x\r\n\r\n", "http");
  t("PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n", "h2");
  t("\x9a\x1f\x22\x33abcdefghijklmnop", "binary");
} else if (process.env.MZ_SELFTEST === "2") {
  (async () => {
    ensureDirs();
    const py = await ensurePython();
    ok("selftest python: " + py);
    const exe = await ensureVenv(py);
    ok("selftest venv: " + exe);
    const r = await run(
      exe,
      ["-c", "import fastapi,sqlalchemy,uvicorn,alembic,grpclib,v2share;print('deps-ok')"],
      { timeout: 90000 }
    );
    console.log(r.code === 0 && /deps-ok/.test(r.out) ? "selftest: OK" : "selftest: FAILED " + (r.err || r.out));
  })().catch((e) => {
    err(e.message);
    process.exitCode = 1;
  });
} else {
  boot();
}
